def block(id,label,desc,source='sandbox',line=1,status='Planned',x=0,y=0,type='worker'):
    return dict(id=id,label=label,description=desc,x=x,y=y,w=240,h=100,type=type,badgeLabel=status,tech=[status],responsibilities=[f'<a href="sources.html#{source}-L{line}" target="_blank" rel="noopener">Read source: {source}, line {line}</a>'])
def cards(id,title,rows,source='sandbox',line=1,cols=3):
    return dict(id=id,label=title,type='system',containers=[],blocks=[block(r[0],r[1],r[2],source,line,x=(i%cols)*310,y=(i//cols)*190,type=['client','http','worker','infra','queue','external'][i%6]) for i,r in enumerate(rows)],edges=[])
def edge(a,b,label=''):return dict(from_=a,to=b,label=label,style='sync')
def connect(tab,edges):tab['edges']=[{'from':a,'to':b,'label':label,'style':'sync'} for a,b,label in edges];return tab
pitch='ROMPE is “Albion Online inside Ragnarok Online”: classic jobs, monsters and cards meet a player economy where choosing a place means choosing risk. The design argues that nostalgia alone is a narrow market, while hunting, crafting, trade and loss give players reasons to return. ORO adds these as layers over classic rules. This is an accepted design plan, not a claim that the whole sandbox is shipped.'
tabs=[cards('overview','01 · Start here',[
('pitch','Albion inside Ragnarok',pitch),('read','Choose a view\nClick for evidence','Each view answers one question. Click a card for context and a source link. Hover traces a connected chain. Drag, zoom, Fit, and export use the upstream renderer.'),('status','Accepted plan\nNot all shipped','The player-path table calls fight shipped; trade, guild-war, defend, cards and minigames partial; Want/craft, account, risk, gather, haul, rift and explore design-only. Source details are a snapshot, not a current runtime audit.')],line=9)]
loop=cards('loop','02 · The economy',[
('want','Want\nPick any recipe','Every recipe is unlocked. Pick the thing you want to make.'),('ledger','Ledger\nFind materials','The Ledger is your goal tracker. The Material Atlas points to monsters, maps, Surges and market prices.'),('gather','Hunt · Gather · Buy','Fight for drops, harvest a Surge or buy missing materials.'),('craft','Craft\nThree ways','Use a Kafra workshop; your own Blacksmith or Alchemist; or commission another player. Player crafters own the high-quality end.'),('cards','Socket cards','Weapons have at least one socket. Classic cards remain part of the design; the combined card overhaul is planned.'),('risk','Wear into risk\nChoose a colour','Risk belongs to the map. Read the border before taking valuables across it.'),('grave','Die? A Grave\nLoss follows zone rules','Blue/yellow drop nothing. Red drops inventory plus equipped crafted if flagged. Black drops everything; ordinary black requires crafted gear. Named abyss maps also permit and loot vanilla gear. A share of dropped items is destroyed; 30% is a starting dial.'),('demand','Replace what was lost','Destroyed and lost goods create demand for materials and crafts. A Grave holds what actually drops, not automatically every item in every zone.'),('survive','Survive? Sell or ship','Sell on the per-city board, or consign bulk goods to a caravan. Death is not required to participate in the economy.')],line=265)
