tabs.append(cards('risk','03 · Risk colours',[
('blue','BLUE · Safe\nNo drops','PvP off. No death drops. Up to three companions. Any gear. These counts are tunable dials.'),('yellow','YELLOW · Flag to fight\nNo drops','Opt-in PvP. No death drops, but crafted durability wears. Up to two companions. Any gear.'),('red','RED · PvP on\nBag + flagged crafted','Inventory drops; equipped crafted gear also drops if flagged. One companion. Any gear. Red is not blanket full-equipment loot.'),('black','BLACK · Crafted only\nEverything drops','PvP on. Full loot. One companion, lootable. Ordinary black zones only allow crafted equipment.'),('abyss','ABYSS · Named exception\nVanilla can drop too','Named abyss black maps permit vanilla gear and loot it too. Which exact maps qualify remains open.'),('border','Read the border\nKnow your carried value','The planned border banner and carried-value meter make risk visible before entry. A Grave destroys a share of what dropped, then exposes the remainder.')],line=479,cols=2))
onboard=[('minute0','0′ · Knife-eating slime','A glowing Poporing has a knife inside. Learn by fighting toward it.'),('minute3','3′ · First Aid ×3','First Aid heals triple in the starter field only. This is a starter-zone dial, not a global formula change.'),('minute5','5′ · First Want','Jellopy opens a recipe goal with a live material counter.'),('minute6','6–8′ · Caravan passes','See stronger players and bots escort a caravan; glimpse a black-zone Grave in the feed.'),('minute8','8′ · Borrowed hero','Rent a level-80 companion for two minutes. The initial build may use a scripted companion until Kafra Hire exists.'),('minute10','10′ · First craft','One-tap craft at the city gate workshop makes a crafted T1 knife.'),('minute12','12′ · Job change','At job level 10, the first job is offered without a job quest.'),('minute15','15′ · Ready to explore','A first-job character, a crafted knife, an active Want. This entire onboarding sequence is a planned playtest sketch, not a shipped script.')]
