group=cards('groups','06 · Who is with you?',[
('account','Account · Up to 12\nA roster, not an army','Up to 12 characters belong to your account. Called companions are limited by risk zone; 12 does not mean all active. Your characters carry an Account tag inside the party.'),('party','Party · Temporary\nNo size cap','The people with you now. No designed size cap; EXP sharing has its own cap. Tags order account, hires, guild and others. First two slots after you are commandable; hires depend on a dial.'),('guild','Guild · Permanent\nEarned promotion','A party can qualify and be promoted; that party is dismantled. One guild per account. Guild membership and current party are separate relationships.'),('war','War sides · Temporary\nGuild replaces party bonds','WoE/GvG stamps event sides by guild for the match. The war side overrides ordinary party relationships; it is not an outer container around a party.'),('engine','Factions · Under the hood','One combat relationship engine decides who may hit whom. No player-facing faction banners or Faction War. Side override takes precedence during events.')],'groups',16,cols=3)
connect(group,[('account','party','tag'),('party','guild','qualify / promote'),('guild','war','event side'),('war','engine','overrides'),('party','engine','normal relation')]);tabs.append(group)
tabs.append(cards('events','07 · Pick an event',[
('caravan','Caravan\nEscort · Raid · Consign','Guard a scheduled Kafra wagon, raid it, or ship warehouse cargo. A broken wagon spills cargo into Graves. Planned; v0 is one long map leg.'),('rift','Rift\nClear · Survive invasion','A solo dungeon with a possible player invader. Gear-capped; designed for 10–15 minutes. Planned.'),('surge','Surge\nHarvest · Contest','Harvest a temporary material vein with an interruptible channel. Richer red/black Surges invite conflict. Planned.'),('roads','Roads\nExplore changing portals','Travel a rotating portal network. Black by default; T6–T8 resources. Planned.'),('outpost','Outposts / WoE\nCapture with your guild','Guilds capture outposts; war modes override ordinary parties. Guild core exists; persistence, scheduling and these new surfaces need work.'),('defence','City defence\nHold the city','Mob War is the defence loop. Caravans supply Readiness; crafters supply defenders. Existing battles are partial foundations, not proof the whole sandbox is live.'),('killboard','Killboard\nRead fights and builds','Read Graves, Rift results, outpost captures and winning builds. The planned public record connects makers, guilds and outcomes.')],line=558))
tabs.append(cards('kafra','08 · Kafra and the world',[
('services','Kafra Corp\nThe world’s infrastructure','Warps, healing/safety, account storage, city warehouses, market board and character hire belong to the same service identity.'),('link','Kafra Link\nA quiet guide','A companion voice through a communicator: short prompts, useful deep links, focus mode and history. It can be muted forever. Planned tray and interface.'),('warehouse','Bulk stays local\nHauling has a purpose','Vanilla Kafra storage stays account-wide and city-agnostic. Crafted goods and sandbox materials use per-city warehouses; board orders settle locally.'),('lore','Invasions are growing\nFind out why','Kafra keeps the digital world running. Defend cities and investigate the growing invasions through events and short messages, season by season.')],line=88,cols=2))
tabs.append(cards('classic','09 · Classic and new',[
('classic','Classic stays\nJobs · Monsters · Cards','Classic jobs and pinned pre-Renewal combat formulas remain the foundation. Vanilla items remain. Cards stay central, with a planned overhaul to fit ORO.'),('new','New sandbox layers\nRisk · Craft · Trade','Crafted losable gear, Want/Atlas/Ledger, local markets, caravans, risk colours, Graves and an account roster extend the world.'),('craftjobs','Crafting jobs change','Blacksmith and Alchemist crafting becomes ORO’s system. This does not mean globally rewriting pinned combat formulas.'),('honesty','Read status, not hype','Accepted design is not shipped implementation. Onboarding and most sandbox loops are planned; existing combat and partial systems provide foundations.')],line=519,cols=2))
