# Native upstream poster bands: adapt circular/rings art to honest compact rows.
def posterband(id,label,items,zone='slate'):
    n=len(items); span=12//n
    return dict(id=id,label=label,zone=zone,blocks=[dict(type='card',col=1+i*span,span=span,ic='flow',title=t,lines=ls) for i,(t,ls) in enumerate(items)])
